"""Add a release's section to its package's CHANGELOG.md on main and push it — changelog.yml.

Usage::

    python .github/scripts/update_changelog.py <tag>

Run from a clone with ``main`` checked out, every tag fetched and an ``origin`` to push to.

The section is generated by git-cliff for exactly this tag's commits — the range from the
package's previous release tag to this one — so it's this release's even when a newer tag of
the same package already exists, and only from commits touching the package
(``--include-path``). It goes right under the file's header, which must be cliff.toml's
``header``; the rest of the file is never regenerated (see cliff.toml).

Runs for several releases may overlap — Actions' ``concurrency`` keeps only one pending run
per group, so it can't queue them — so each attempt starts from the latest main, and a push
rejected because main moved on is retried on top of it. A release whose section is already
there is left alone, so re-running is safe.

The git-cliff command comes from ``$GIT_CLIFF`` (default ``git-cliff``), e.g.
``uvx --from git-cliff==2.14.2 git-cliff``; ``$GITHUB_REPO`` (``owner/repo``) feeds the links.
"""

from __future__ import annotations

import os
import shlex
import subprocess
import sys
import time
import tomllib
from collections.abc import Callable
from pathlib import Path

from release_package import Release, ReleaseError, resolve

ATTEMPTS = 5


def _git(repo: Path, *args: str, check: bool = True) -> subprocess.CompletedProcess[str]:
    return subprocess.run(
        ["git", *args], cwd=repo, check=check, capture_output=True, text=True, encoding="utf-8"
    )


def previous_tag(repo: Path, release: Release) -> str | None:
    """The package's release tag before ``release.tag`` in history, if there is one."""
    matches = [arg for glob in release.tag_globs for arg in ("--match", glob)]
    result = _git(
        repo, "describe", "--tags", "--abbrev=0", *matches, f"{release.tag}^", check=False
    )
    return result.stdout.strip() if result.returncode == 0 else None


def release_section(repo: Path, release: Release, git_cliff: list[str]) -> str:
    """The release's changelog section: a heading and its entries, nothing else."""
    previous = previous_tag(repo, release)
    if previous is None:
        # git-cliff needs A..B; the root commit itself is left out, which only matters for a
        # package created in the repository's very first commit.
        root = _git(repo, "rev-list", "--max-parents=0", release.tag).stdout.split()[-1]
        commits = f"{root}..{release.tag}"
    else:
        commits = f"{previous}..{release.tag}"
    # What git-cliff can't tell on its own once --include-path drops commits: the tagged
    # commit is often outside the package (a merge or docs commit), which loses the tag — so
    # --tag names the release and CHANGELOG_DATE gives its date (the tagged commit's, as
    # git-cliff itself uses); and the previous release can have no package commits at all
    # (ranobelib's legacy v0.13.0), which loses the heading's compare link.
    env = dict(os.environ)
    env["CHANGELOG_DATE"] = _git(repo, "log", "-1", "--format=%cs", release.tag).stdout.strip()
    if previous is not None:
        env["CHANGELOG_PREVIOUS_TAG"] = previous
    else:
        env.pop("CHANGELOG_PREVIOUS_TAG", None)
    result = subprocess.run(
        [
            *git_cliff,
            "--config", str(repo / "cliff.toml"),
            "--include-path", f"{release.directory}/**",
            "--tag-pattern", release.tag_pattern,
            "--tag", release.tag,
            "--strip", "all",
            "--offline",
            commits,
        ],
        cwd=repo,
        env=env,
        check=True,
        capture_output=True,
        text=True,
        encoding="utf-8",
    )  # fmt: skip
    return result.stdout.strip("\n") + "\n"


def _header(repo: Path) -> str:
    text = (repo / "cliff.toml").read_bytes().decode("utf-8").replace("\r\n", "\n")
    header: str = tomllib.loads(text)["changelog"]["header"]
    return header


def update_changelog(
    tag: str,
    *,
    repo: Path,
    git_cliff: list[str],
    attempts: int = ATTEMPTS,
    retry_delay: float = 5.0,
    before_push: Callable[[int], None] | None = None,
) -> str:
    """Add ``tag``'s section to its package's CHANGELOG.md on main and push it.

    Args:
        tag: The release tag, ``<prefix>-vX.Y.Z``.
        repo: A clone with ``main`` checked out and an ``origin`` to push to.
        git_cliff: The command running git-cliff.
        attempts: How many times to try before giving up on a push main keeps rejecting.
        retry_delay: Seconds to wait before retry ``n``, times ``n``.
        before_push: Called with the attempt number right before each push. For tests.

    Returns:
        ``"pushed"``, ``"already there"`` or ``"no entries"`` (no changelog-worthy commits).

    Raises:
        ReleaseError: If the tag doesn't name a known package, the CHANGELOG.md doesn't start
            with cliff.toml's header, or every push was rejected.
    """
    release = resolve(tag, check_version=False, root=repo)
    path = repo / release.directory / "CHANGELOG.md"
    heading = f"## [{release.version}]"
    section = release_section(repo, release, git_cliff)
    if heading not in section:
        return "no entries"

    for attempt in range(1, attempts + 1):
        _git(repo, "fetch", "origin", "main")
        _git(repo, "reset", "--hard", "origin/main")
        text = path.read_bytes().decode("utf-8").replace("\r\n", "\n")
        if heading in text:
            return "already there"
        header = _header(repo)
        if not text.startswith(header):
            raise ReleaseError(
                f"{release.directory}/CHANGELOG.md doesn't start with cliff.toml's header; "
                "fix one to match the other, or the section can't be placed."
            )
        rest = text[len(header) :]
        path.write_bytes((header + section + ("\n" + rest if rest else "")).encode("utf-8"))
        _git(repo, "add", str(path))
        _git(repo, "commit", "-m", f"docs: update {release.directory}/CHANGELOG.md for {tag}")

        if before_push is not None:
            before_push(attempt)
        if _git(repo, "push", "origin", "HEAD:main", check=False).returncode == 0:
            return "pushed"
        print(f"Push rejected (attempt {attempt}/{attempts}); retrying on the new main.")
        if attempt < attempts:
            time.sleep(retry_delay * attempt)
    raise ReleaseError(f"Couldn't push {path.name} for {tag}: main kept moving.")


def main(argv: list[str]) -> int:
    if len(argv) != 1:
        print(__doc__, file=sys.stderr)
        return 2
    git_cliff = shlex.split(os.environ.get("GIT_CLIFF", "git-cliff"))
    try:
        outcome = update_changelog(argv[0], repo=Path.cwd(), git_cliff=git_cliff)
    except ReleaseError as exc:
        print(f"::error::{exc}")
        return 1
    print(f"{argv[0]}: {outcome}")
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
